			function onBodyPropertyChange(/* cpr.events.CPropertyChangeEvent */ e){
			    
			    console.log("e.property 000::::: " + e.property);
			    console.log("e.property 111::::: " + e.newValue);
			    
			    if (e.property == "type") {
			        if(e.newValue == "READ") {
			            
			            CUtype = e.newValue;
			            util.Control.setReadOnly(app, true, "grpData");
			            util.Control.setEnable(app, false, ["cbx5", "cbx6", "cbx7", "cbx8"]);
			            util.Control.setVisible(app, true, ["opt10", "btnRevise", "btnDelete", "btnClose"]);
			            onBodyLoadUpdate();
			            
			        } else if (e.newValue == "CREATE") {
			            
			            CUtype = e.newValue;
			            util.Control.setVisible(app, true, ["dti1", "cmnTimeCombo1", "btnSave", "btnClose"]);
			            onBodyLoadInsert();
			            
			        }
			        
			    } else if (e.property == "data") {
			        
			        app.lookup("dmSearch").build(e.newValue);
			        console.log("22222222222 ==" + app.lookup("dmSearch").getValue("EDU_ESTBL_SN"));
			        
			    }
			}

